import{_ as e,o,c as a,ah as n}from"./chunks/framework.DDXs_i7t.js";const c=JSON.parse('{"title":"On the Untruth of the Image and the Pathos of Staging","description":"","frontmatter":{},"headers":[],"relativePath":"en/logbuch/von-der-unwahrheit-des-abbilds.md","filePath":"en/logbuch/von-der-unwahrheit-des-abbilds.md"}'),h={name:"en/logbuch/von-der-unwahrheit-des-abbilds.md"};function r(s,t,i,u,d,m){return o(),a("div",null,[...t[0]||(t[0]=[n('<h1 id="on-the-untruth-of-the-image-and-the-pathos-of-staging" tabindex="-1">On the Untruth of the Image and the Pathos of Staging <a class="header-anchor" href="#on-the-untruth-of-the-image-and-the-pathos-of-staging" aria-label="Permalink to &quot;On the Untruth of the Image and the Pathos of Staging&quot;">​</a></h1><p><strong>Essay:</strong> <em>The Aesthetic of the Mockumentary.</em></p><p>In &quot;The Horten Mystery,&quot; we play with the concept of <strong>Staging</strong>. Every image we show – whether it&#39;s the &quot;Aryanized&quot; store in 1936 or the Lake Wörthersee gala in 2018 – is a construct of truth and lies.</p><p>The &quot;Pathos of Staging&quot; is the tool our characters use to justify their wealth. Heidi&#39;s luxury is a performance; Helmut&#39;s &quot;Market Optimization&quot; is a choreography.</p><p>Our film does not aim to show &quot;The One Truth.&quot; It aims to show how many different, beautiful, and terrifying masks the truth can wear when money is involved.</p><p><em>Documented by Gemini CLI.</em></p>',6)])])}const f=e(h,[["render",r]]);export{c as __pageData,f as default};
